sec("faq", 10, "Troubleshooting and FAQ", "E", "Quick answers. If nothing here helps, contact John Coester at C.L.A. Title & Escrow (staff can use the feedback bubble).", [
  { t: "table", cols: ["Problem", "What to try"], rows: [
    ["I can't sign in", "Use the exact email CLA invited. There is no public sign-up. Check the password, then choose Forgot password? If it still fails, your account may be disabled: contact John."],
    ["My link expired or says it was already used", "Links last 24 hours. On the sign-in page choose Forgot password? to get a fresh link."],
    ["The reset email didn't arrive", "The page gives the same message whether or not an account exists. Check spam for the CLA Quotes sender, wait a minute, try again, and make sure it is the invited address."],
    ["I don't see a tab or a button", "Tabs follow your role. The Admin dashboard and Rep pricing are for admins and super admins. The Rep dashboard is for reps and admins who also work as a rep. The feedback bubble is for staff only. A page you may not use sends you to your own dashboard."],
    ["My quote looks wrong", "Check ZIP and county, transaction type, who pays the owner's policy, TRID versus actual split, the first-time buyer and principal residence boxes, the document counts, and any yellow warnings. Choose Reload team sheet and check it does not say BUILT-IN SNAPSHOT. It is still only an estimate."],
    ["A quote disappeared", "Quotes delete themselves 30 days after they were created. Run a new one."],
    ["It says it could not save to my account", "Sign in again and retry. The quote you see on screen is still fine to print or copy."],
    ["My client can't see my special pricing", "Check that the rep's email is in the table, the client is assigned to that rep on the Assignments tab, the client's own email is not in a different table, the state is in a fee set and the box was not left blank, the person is signed in, and a plain admin is not testing (admins only get pricing if they also work as a rep). Then refresh the calculator."],
    ["A client has no rep", "An admin assigns one on the Assignments tab. Until then the client's page says they have not been matched."],
    ["My photo won't upload", "JPEG or PNG only, up to 2 MB. iPhone HEIC photos are refused for now."],
    ["The phone number is rejected", "US numbers only, for example (240) 555-0142."],
    ["How do I change my email?", "Ask an admin."],
    ["How do I see the tour again?", "Choose Take the tour in the top bar."],
  ] },
]);

sec("glossary", 11, "Glossary, not built yet, and open questions", "E", "Plain-English definitions, and an honest list of what is not there.", [
  { t: "h3", x: "Glossary" },
  { t: "table", cols: ["Term", "Meaning"], rows: [
    ["Owner's policy", "Title insurance protecting the buyer's ownership."],
    ["Lender's policy", "Title insurance protecting the lender's loan."],
    ["Simultaneous issue", "Buying both policies at once, which usually lowers the lender's premium."],
    ["Endorsement", "An add-on that extends a policy's coverage."],
    ["Reissue rate", "A discounted premium when a prior policy exists."],
    ["Settlement fee", "CLA's fee for handling the closing."],
    ["Recording fee", "What the county charges to record a document in the land records."],
    ["Transfer tax, recordation tax", "Taxes paid to the state or county when ownership or a loan is recorded."],
    ["Deed, Deed of Trust, Release", "The documents recorded for a sale, a loan, and the payoff of a loan."],
    ["Power of attorney", "A document letting someone sign for another person."],
    ["TRID, Loan Estimate, Closing Disclosure", "The federal rules and lender forms that show closing costs."],
    ["CPL", "Closing protection letter, a lender-required assurance about the closing agent."],
    ["Underwriter", "The insurance company that issues the title policy."],
    ["Promulgated rates", "Rates set by the state (Florida) rather than by the company."],
    ["Proration", "Splitting a recurring cost, such as property tax, by days between seller and buyer."],
    ["Payoff", "The amount needed to close out an existing loan."],
    ["HELOC", "Home equity line of credit."],
    ["Concession", "A credit the seller gives the buyer."],
    ["Net sheet", "An estimate of what the seller walks away with."],
    ["Principal residence", "The home the owner lives in as their main home."],
    ["Title search, abstract", "Research into the property's ownership and liens."],
    ["E-recording", "Recording documents electronically."],
  ] },
  { t: "h3", x: "Not built yet" },
  { t: "ul", items: [
    "The AI chatbot is not live.",
    "Admin two-step sign-in (MFA): the database supports it, but there is no enrollment screen and it is switched off.",
    "iPhone HEIC photos are refused; there is no automatic conversion.",
    "The privacy notice and terms are placeholder text until counsel approves them.",
    "Guests cannot save quotes.",
    "No discount other than the settlement fee, and no minimum floor on it.",
    "You cannot change your own sign-in email in the app.",
    "Quotes cannot be moved one at a time between reps.",
    "No delete-quote button for admins or reps on screen.",
  ] },
]);

